#!/bin/bash
# Load TPC-H data generated by the official dbgen (scale factor 0.1) into database "tpch".
# usage: trackH/load.sh <dir with *.tbl>
set -euo pipefail   # pipefail: a failing sed inside the pipe must stop the load (it once loaded EMPTY tables)
D=${1:-external/tpch}; HERE=$(dirname "$0")
for t in region nation part supplier partsupp customer orders lineitem; do
  [ -s "$D/$t.tbl" ] || { echo "missing $D/$t.tbl — generate TPC-H data first (see README)"; exit 1; }
done
psql -q -d tpch -f "$HERE/schema.sql"
for t in region nation part supplier partsupp customer orders lineitem; do
  sed 's/|$//' "$D/$t.tbl" | psql -q -d tpch -c "\copy $t FROM STDIN WITH (FORMAT text, DELIMITER '|')"
done
psql -q -d tpch -c "VACUUM ANALYZE;"
psql -d tpch -Atc "SELECT relname, n_live_tup FROM pg_stat_user_tables ORDER BY 2 DESC;"
